from scipy.optimize import least_squares
def model(p):
    c0,c1,c2,c3,cv,F,w,ph=p
    return c0+c1*x+c2*x**2+c3*x**3+cv*v+F*np.cos(w*t+ph)
best=None
for w0 in np.linspace(0.2,6,30):
    r=least_squares(lambda p: model(p)-a, [0,-1,0,0,0,1,w0,0])
    if best is None or r.cost<best.cost: best=r
print(best.x, best.cost, 1-2*best.cost/np.sum((a-a.mean())**2))
res=model(best.x)-a
for name,arr in [('t',t),('x',x),('v',v)]:
